<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$fineRate=(int)setting('fine_per_day',500);
$rows=$pdo->query("SELECT l.id,u.name,u.username,c.code,b.title,l.loan_date,l.due_date,DATEDIFF(CURDATE(),l.due_date) late_days FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE l.returned_at IS NULL AND l.due_date<CURDATE() ORDER BY l.due_date")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Keterlambatan</title><link rel=stylesheet href=../public/style.css></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>◷ Keterlambatan</h1><div class=cards><div class=card>Transaksi terlambat<div class=num><?=count($rows)?></div></div><div class=card>Denda / hari<div class=num>Rp <?=number_format($fineRate,0,',','.')?></div></div></div><br><table class=table><tr><th>Anggota</th><th>Buku</th><th>Jatuh Tempo</th><th>Terlambat</th><th>Estimasi Denda</th><th>Aksi</th></tr><?php foreach($rows as $r):$fine=$r['late_days']*$fineRate;?><tr><td><?=e($r['name'])?><br><small><?=e($r['username'])?></small></td><td><?=e($r['code'].' - '.$r['title'])?></td><td><?=e($r['due_date'])?></td><td><?=$r['late_days']?> hari</td><td>Rp <?=number_format($fine,0,',','.')?></td><td><a class=btn href=returns.php>Pengembalian</a></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan=6>🎉 Tidak ada transaksi yang terlambat.</td></tr><?php endif?></table></main></div></body></html>
